<?php
require_once dirname(__DIR__).'/rent_reminder_lib.php';admin_required();cfg();$msg='';$err='';
function rr_post($k){return trim((string)($_POST[$k]??''));}
function rr_date($v){$d=DateTimeImmutable::createFromFormat('!Y-m-d',$v);return $d&&$d->format('Y-m-d')===$v;}
try{
 if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$a=rr_post('action');
 if($a==='install'){foreach(explode(';',file_get_contents(dirname(__DIR__).'/rent_schema.sql')) as $sql)if(trim($sql))db()->exec($sql);db()->prepare('INSERT IGNORE INTO lease_rent_settings(id,gas_key) VALUES(1,?)')->execute([token(32)]);}
 elseif($a==='settings'){db()->prepare('UPDATE lease_rent_settings SET template_code=?,sender_profile=?,enabled=? WHERE id=1')->execute([rr_post('template_code'),rr_post('sender_profile'),isset($_POST['enabled'])?1:0]);}
 elseif($a==='save'){
 $id=(int)rr_post('id');$cid=(int)rr_post('contract_id');$keys=['property','tenant','phone','rent','pay_day','bank','account_no','holder','late_rate','start_date','end_date','lead_days','send_time'];$v=[];foreach($keys as $k)$v[$k]=rr_post($k);
 $v['phone']=preg_replace('/\D/','',$v['phone']);foreach(['property','tenant','bank','holder'] as $k)if($v[$k]==='')throw new RuntimeException('필수항목을 입력하세요: '.$k);
 if(!preg_match('/^01\d{8,9}$/',$v['phone'])||!ctype_digit($v['account_no'])||!ctype_digit($v['rent'])||(int)$v['rent']<=0||!ctype_digit($v['pay_day'])||(int)$v['pay_day']<1||(int)$v['pay_day']>31||!ctype_digit($v['lead_days'])||(int)$v['lead_days']>31||!is_numeric($v['late_rate'])||$v['late_rate']<0||$v['late_rate']>100||!rr_date($v['start_date'])||!rr_date($v['end_date'])||$v['start_date']>$v['end_date']||!preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d$/',$v['send_time']))throw new RuntimeException('금액, 날짜, 계좌, 연락처 및 발송 설정을 확인하세요.');
 if($cid){$q=db()->prepare("SELECT id FROM contracts WHERE id=? AND status='completed'");$q->execute([$cid]);if(!$q->fetch())throw new RuntimeException('완료 계약만 연결할 수 있습니다.');}
 $v['contract_id']=$cid?:null;$v['active']=isset($_POST['active'])?1:0;$cols=array_keys($v);if($id){$q=db()->prepare('UPDATE lease_rent_reminders SET '.implode(',',array_map(fn($k)=>"$k=?",$cols)).' WHERE id=?');$q->execute([...array_values($v),$id]);}else{db()->prepare('INSERT INTO lease_rent_reminders('.implode(',',$cols).') VALUES('.implode(',',array_fill(0,count($cols),'?')).')')->execute(array_values($v));}
 }elseif($a==='toggle'){db()->prepare('UPDATE lease_rent_reminders SET active=1-active WHERE id=?')->execute([(int)rr_post('id')]);}
 elseif(in_array($a,['send','test'],true)){if($a==='test'&&!preg_match('/^01\d{8,9}$/',rr_post('test_phone')))throw new RuntimeException('테스트 번호 확인');if($a==='send'&&!rr_settings()['enabled'])throw new RuntimeException('알림톡 발송 설정을 활성화하세요.');$msg=rr_dispatch((int)rr_post('id'),$a==='test'?rr_post('test_phone'):null);}
 elseif(in_array($a,['skip','restore','resolve'],true)){$from=['skip'=>'pending','restore'=>'skipped','resolve'=>'unknown'][$a];$to=['skip'=>'skipped','restore'=>'pending','resolve'=>'accepted'][$a];db()->prepare('UPDATE lease_rent_send_queue SET status=? WHERE id=? AND status=?')->execute([$to,(int)rr_post('id'),$from]);}
 rr_generate();$msg=$msg?:'처리되었습니다.';
 }
}catch(Throwable $ex){$err=$ex instanceof PDOException?'DB 오류: 설치 여부 또는 중복 계약을 확인하세요.':$ex->getMessage();}
$s=null;try{$s=rr_settings();if($s)rr_generate();}catch(Throwable $ignore){}
function rr_hidden($a,$id=0){echo '<input type="hidden" name="csrf" value="'.e(csrf()).'"><input type="hidden" name="action" value="'.e($a).'"><input type="hidden" name="id" value="'.(int)$id.'">';}
function rr_btn($a,$id,$label){echo '<form method="post" style="display:inline-block" onsubmit="return confirm(\'처리하시겠습니까?\')">';rr_hidden($a,$id);echo '<button class="btn gray">'.e($label).'</button></form> ';}
?>
<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>월차임 납부 안내</title><link rel="stylesheet" href="../assets/app.css"><style>.wrap{max-width:1450px}.btn{font-size:14px;padding:8px 12px}input[type=checkbox]{width:auto}.list{font-size:15px}.metrics{display:flex;gap:16px;flex-wrap:wrap}.metrics div{flex:1;min-width:130px;background:#edf4ff;padding:16px;border-radius:12px}.metrics b{display:block;font-size:28px}details{margin:10px 0}summary{cursor:pointer;font-weight:bold}</style></head><body><?php include '_top.php';?><main class="wrap"><h1>월차임 납부 안내 관리</h1><?php if($msg):?><div class="alert ok"><?=e($msg)?></div><?php endif;if($err):?><div class="alert err"><?=e($err)?></div><?php endif;if(!$s):?><section class="card"><p>신규 테이블만 설치합니다. 기존 계약은 변경하지 않습니다.</p><form method="post"><?php rr_hidden('install');?><button class="btn">DB 초기 설치</button></form></section><?php else:
$rows=db()->query('SELECT * FROM lease_rent_reminders ORDER BY id DESC')->fetchAll();$month=(string)($_GET['month']??date('Y-m'));if(!preg_match('/^\d{4}-\d{2}$/',$month))$month=date('Y-m');$q=db()->prepare('SELECT q.*,r.active,r.start_date,r.end_date FROM lease_rent_send_queue q JOIN lease_rent_reminders r ON r.id=q.reminder_id WHERE rent_month=? ORDER BY scheduled_at');$q->execute([$month]);$queue=$q->fetchAll();$counts=array_count_values(array_column($queue,'status'));$labels=['pending'=>'발송 예정','accepted'=>'접수 완료','failed'=>'실패','unknown'=>'결과 확인 필요','sending'=>'처리 중 / 확인 필요','skipped'=>'발송 제외'];
$edit=[];$id=(int)($_GET['edit']??0);foreach($rows as $r)if($r['id']==$id)$edit=$r;$contracts=db()->query("SELECT * FROM contracts WHERE status='completed' ORDER BY id DESC")->fetchAll();$import=(int)($_GET['import']??0);foreach($contracts as $c)if($import&&$c['id']==$import&&!$id){$edit=['contract_id'=>$import,'property'=>trim($c['property_address'].' '.$c['property_detail']),'tenant'=>$c['lessee_name'],'phone'=>$c['lessee_phone'],'rent'=>$c['monthly_rent'],'pay_day'=>$c['payment_day']?:date('j',strtotime($c['start_date'])),'late_rate'=>$c['late_rate'],'start_date'=>$c['start_date'],'end_date'=>$c['end_date']];$originalAccount=$c['rent_account'];}
?>
<section class="card"><div class="metrics"><?php foreach(['등록 계약'=>count($rows),'발송 예정'=>$counts['pending']??0,'접수 완료'=>$counts['accepted']??0,'실패 / 확인 필요'=>($counts['failed']??0)+($counts['unknown']??0)+($counts['sending']??0)] as $k=>$n):?><div><?=e($k)?><b><?=$n?></b></div><?php endforeach;?></div></section>
<section class="card"><details><summary>알림톡 및 자동발송 설정</summary><form method="post"><?php rr_hidden('settings');?><div class="grid"><label>템플릿 코드<input name="template_code" value="<?=e($s['template_code'])?>"></label><label>발신 프로필 (필요 시)<input name="sender_profile" value="<?=e($s['sender_profile'])?>"></label></div><p>기존 문자설정의 뿌리오 계정 및 인증키를 사용합니다.</p><label><input type="checkbox" name="enabled" <?=$s['enabled']?'checked':''?>> 실제 발송 활성화</label><button class="btn">설정 저장</button></form><label>GAS 인증키 (외부 공유 금지)<input readonly value="<?=e($s['gas_key'])?>"></label></details></section>
<section class="card"><details <?=$id||$import?'open':''?>><summary>＋ 계약 신규 등록 / 수정</summary><form method="get"><label>완료 전자계약 불러오기<select name="import"><option value="0">선택</option><?php foreach($contracts as $c):?><option value="<?=$c['id']?>"><?=e($c['lessee_name'].' / '.$c['property_address'])?></option><?php endforeach;?></select></label><button class="btn gray">불러오기</button></form><?php if(isset($originalAccount)):?><p>기존 입금정보: <?=e($originalAccount)?> — 은행·계좌·예금주를 직접 확인하여 입력하세요.</p><?php endif;?><form method="post" onsubmit="return confirm('계약정보를 저장하시겠습니까?')"><?php rr_hidden('save',$id);?><input type="hidden" name="contract_id" value="<?=e($edit['contract_id']??0)?>"><div class="grid"><?php foreach(['property'=>['계약물건','text',''],'tenant'=>['임차인','text',''],'phone'=>['휴대전화','tel',''],'rent'=>['월차임 (원)','number',''],'pay_day'=>['매월 납부일 (1~31)','number','25'],'bank'=>['입금은행','text',''],'account_no'=>['계좌번호 (숫자만)','text',''],'holder'=>['예금주','text',''],'late_rate'=>['지연배상금률 (연 %)','number','10'],'start_date'=>['계약 시작일','date',date('Y-m-d')],'end_date'=>['계약 종료일','date',''],'lead_days'=>['납부일 며칠 전 발송 (0~31)','number','1'],'send_time'=>['자동발송 시간','time','09:00']] as $k=>[$label,$type,$default]):?><label><?=e($label)?><input required name="<?=$k?>" type="<?=$type?>" <?=$k==='late_rate'?'step="0.01"':''?> <?=$k==='account_no'?'pattern="[0-9]+" inputmode="numeric"':''?> value="<?=e($k==='send_time'?substr($edit[$k]??$default,0,5):($edit[$k]??$default))?>"></label><?php endforeach;?></div><label><input type="checkbox" name="active" <?=($edit['active']??1)?'checked':''?>> 매월 자동발송 활성화</label> <div style="display:flex; gap:10px; align-items:center; margin-top:15px;">
    <button type="submit" class="btn"
            style="padding:10px 22px; font-size:14px;">
        저장
    </button>

    <a href="rent_reminders.php"
       style="display:inline-flex;
              align-items:center;
              justify-content:center;
