</div></form></details></section>
<section class="card"><h2>등록 계약</h2><div class="table-wrap"><table class="list"><tr><th>물건 / 임차인</th><th>금액</th><th>납부일 / 발송</th><th>계약기간</th><th>관리</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['property'])?><br><?=e($r['tenant'])?> · <?=$r['contract_id']?'전자':'오프라인'?></td><td><?=money($r['rent'])?></td><td>매월 <?=$r['pay_day']?>일 / <?=$r['lead_days']?>일 전 <?=e($r['send_time'])?></td><td><?=e($r['start_date'].' ~ '.$r['end_date'])?></td><td><a class="btn" href="?edit=<?=$r['id']?>">수정</a> <?php rr_btn('toggle',$r['id'],$r['active']?'중지':'활성화');?></td></tr><?php endforeach;?></table></div></section>
<section class="card"><h2>월별 발송 리스트</h2><form method="get"><input type="month" name="month" value="<?=e($month)?>" style="width:auto"><button class="btn">조회</button></form><div class="table-wrap"><table class="list"><tr><th>물건 / 임차인</th><th>납부일 / 금액</th><th>발송예정</th><th>상태</th><th>관리</th></tr><?php foreach($queue as $v):$r=json_decode($v['snapshot'],true);$valid=$v['active']&&$v['due_date']>=date('Y-m-d')&&$v['due_date']>=$v['start_date']&&$v['due_date']<=$v['end_date'];?><tr><td><?=e($r['property'].' / '.$r['tenant'])?></td><td><?=e($v['due_date'])?> / <?=money($r['rent'])?></td><td><?=e($v['scheduled_at'])?></td><td><?=e($labels[$v['status']]??$v['status'])?><?=!$valid&&$v['status']==='pending'?' (발송 불가)':''?></td><td><?php if($valid&&in_array($v['status'],['pending','failed']))rr_btn('send',$v['id'],$v['status']==='failed'?'재발송':'즉시 발송');if($v['status']==='pending')rr_btn('skip',$v['id'],'이번 달 제외');if($v['status']==='skipped')rr_btn('restore',$v['id'],'제외 해제');?><details><summary>미리보기 / 테스트</summary><pre style="white-space:pre-wrap"><?=e(implode("\n",rr_vars($r,$v['due_date'])))?></pre><form method="post"><?php rr_hidden('test',$v['id']);?><input name="test_phone" required placeholder="관리자 테스트 번호"><button class="btn">테스트 발송</button></form></details></td></tr><?php endforeach;?></table></div></section>
<section class="card"><h2>최근 발송 이력 (100건)</h2><div class="table-wrap"><table class="list"><tr><th>일시</th><th>발송건</th><th>상태</th><th>참조키 / 결과</th></tr><?php foreach(db()->query('SELECT * FROM lease_rent_send_logs ORDER BY id DESC LIMIT 100') as $l):?><tr><td><?=e($l['created_at'])?></td><td><?=e($l['queue_id'])?></td><td><?=e($l['status'])?></td><td><details><summary><?=e($l['ref_key'])?></summary><pre style="white-space:pre-wrap;max-width:600px"><?=e($l['result_json'])?></pre></details></td></tr><?php endforeach;?></table></div></section><?php endif;?></main></body></html>
